"""Data transformation pipeline."""

import re
import logging
from typing import Any, Callable, Dict, List, Optional, TypeVar

logger = logging.getLogger(__name__)

# Registry of named transforms
_transforms: Dict[str, Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]] = {}


def register(
    name: str,
    fn: Callable[[Dict[str, Any]], Optional[Dict[str, Any]]],
) -> None:
    """Register a named transform function."""
    _transforms[name] = fn


def get_transform(
    name: str
) -> Optional[Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]]:
    """Look up a registered transform by name."""
    return _transforms.get(name)


def apply_transforms(
    record_data: Dict[str, Any],
    transform_names: List[str],
) -> Optional[Dict[str, Any]]:
    """Apply a list of named transforms to a record's data dict."""
    current: Optional[Dict[str, Any]] = record_data
    for name in transform_names:
        fn = _transforms.get(name)
        if fn is None:
            logger.warning(f"Unknown transform: {name}")
            continue
        result = fn(current)
        if result is None:
            return None  # filtered out
        current = result
    return current


def compose(
    *fns: Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]
) -> Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]:
    """Compose multiple transform functions into a single function."""
    def composed(data: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        current: Optional[Dict[str, Any]] = data
        for fn in fns:
            if current is None:
                return None
            current = fn(current)
        return current
    return composed


# ---- Built-in transforms ----

def normalize_keys(
    data: Dict[str, Any]
) -> Dict[str, Any]:
    """Convert all keys to lowercase with underscores."""
    result: Dict[str, Any] = {}
    for key, value in data.items():
        normalized = re.sub(r"[^a-zA-Z0-9]", "_", key).lower()
        normalized = re.sub(r"_+", "_", normalized).strip("_")
        result[normalized] = value
    return result


def strip_whitespace(
    data: Dict[str, Any]
) -> Dict[str, Any]:
    """Strip leading/trailing whitespace from all string values."""
    result: Dict[str, Any] = {}
    for key, value in data.items():
        if isinstance(value, str):
            result[key] = value.strip()
        else:
            result[key] = value
    return result


def remove_nulls(
    data: Dict[str, Any]
) -> Dict[str, Any]:
    """Remove keys with None values."""
    return {k: v for k, v in data.items() if v is not None}


def add_computed_fields(
    data: Dict[str, Any]
) -> Dict[str, Any]:
    """Add computed fields based on existing data."""
    result: Dict[str, Any] = dict(data)
    if "first_name" in data and "last_name" in data:
        result["full_name"] = f"{data['first_name']} {data['last_name']}"
    if "price" in data and "quantity" in data:
        try:
            result["total"] = float(data["price"]) * int(data["quantity"])
        except (ValueError, TypeError):
            result["total"] = 0
    return result


def filter_by_fields(
    required_fields: List[str]
) -> Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]:
    """Return a transform that filters out records missing required fields."""
    def _filter(data: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        for field in required_fields:
            if field not in data or data[field] is None:
                return None
        return data
    return _filter


def rename_fields(
    mapping: Dict[str, str]
) -> Callable[[Dict[str, Any]], Dict[str, Any]]:
    """Return a transform that renames fields according to a mapping."""
    def _rename(data: Dict[str, Any]) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for key, value in data.items():
            new_key = mapping.get(key, key)
            result[new_key] = value
        return result
    return _rename


def build_pipeline(
    config: Dict[s

    config: Dict[str, Any]
) -> Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]:
    """Build a transform pipeline from a config dict."""
    steps: List[str] = config.get("transforms", [])
    fns: List[Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]] = []
    for step in steps:
        name = step if isinstance(step, str) else step.get("name")
        fn = get_transform(name)
        if fn is not None:
            fns.append(fn)
        else:
            logger.warning(f"Skipping unknown transform in pipeline: {name}")
    return compose(*fns)


# Register built-in transforms
register("normalize_keys", normalize_keys)
register("strip_whitespace", strip_whitespace)
register("remove_nulls", remove_nulls)
register("add_computed_fields", add_computed_fields)

"""Simple TTL cache for expensive lookups."""

import time
import functools
from typing import Any, Callable, Dict, Optional, Tuple, TypeVar

T = TypeVar("T")


class TTLCache:
    def __init__(self, ttl_seconds: int = 300, max_size: int = 1000) -> None:
        self.ttl: int = ttl_seconds
        self.max_size: int = max_size
        self._store: Dict[str, Tuple[Any, float]] = {}

    def get(self, key: str) -> Optional[Any]:
        entry = self._store.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if time.time() > expires_at:
            del self._store[key]
            return None
        return value

    def set(self, key: str, value: Any) -> None:
        if len(self._store) >= self.max_size:
            self._evict_expired()
            if len(self._store) >= self.max_size:
                oldest_key = min(
                    self._store, key=lambda k: self._store[k][1]
                )
                del self._store[oldest_key]
        self._store[key] = (value, time.time() + self.ttl)

    def delete(self, key: str) -> None:
        self._store.pop(key, None)

    def clear(self) -> None:
        self._store.clear()

    def _evict_expired(self) -> None:
        now = time.time()
        expired = [
            k for k, (_, exp) in self._store.items() if now > exp
        ]
        for k in expired:
            del self._store[k]

    @property
    def size(self) -> int:
        return len(self._store)

    def stats(self) -> Dict[str, int]:
        now = time.time()
        active = sum(1 for _, (_, exp) in self._store.items() if now <= exp)
        return {
            "total_entries": len(self._store),
            "active": active,
            "expired": len(self._store) - active,
        }


_default_cache: Optional[TTLCache] = None


def get_default_cache(ttl: int = 300) -> TTLCache:
    global _default_cache
    if _default_cache is None:
        _default_cache = TTLCache(ttl_seconds=ttl)
    return _default_cache


def cached(ttl: int = 300) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Decorator that caches function results based on arguments."""
    def decorator(fn: Callable[..., Any]) -> Callable[..., Any]:
        cache = TTLCache(ttl_seconds=ttl)

        @functools.wraps(fn)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            cache_key = str(args) + str(sorted(kwargs.items()))
            result = cache.get(cache_key)
            if result is not None:
                return result
            result = fn(*args, **kwargs)
            cache.set(cache_key, result)
            return result

        wrapper.cache = cache
        wrapper.cache_clear = cache.clear
        return wrapper
    return decorator

